package com.personal.assistant.module.report.mapper;public final class ReportStatsSql{private ReportStatsSql(){}public static String sql(){return"select "+"(select count(*) from task_item where user_id=#{uid} and status='COMPLETED' and status_changed_at::date between #{start} and #{end}) completed_tasks,"+"(select count(*) from task_item where user_id=#{uid} and created_at::date between #{start} and #{end}) created_tasks,"+"(select coalesce(sum(duration_minutes),0) from learning_record where user_id=#{uid} and record_time::date between #{start} and #{end}) learning_minutes,"+"(select count(*) from dev_log where user_id=#{uid} and occurred_at::date between #{start} and #{end}) dev_log_count,"+"(select coalesce(sum(amount),0) from finance_transaction where user_id=#{uid} and direction='INCOME' and transaction_time::date between #{start} and #{end}) income,"+"(select coalesce(sum(amount),0) from finance_transaction where user_id=#{uid} and direction='EXPENSE' and transaction_time::date between #{start} and #{end}) expense";}}
